-- K9 Academy Esami / Dogsitter 600 triplette (200 nuclei x 3 formulazioni)
-- Da eseguire UNA SOLA VOLTA nel Supabase SQL Editor dopo un backup.
-- Aggiorna ESCLUSIVAMENTE la disciplina dogsitter; conserva i record storici
-- disattivati, necessari per integrita di esami e report gia svolti.
-- La banca di esame e composta da ESATTAMENTE 600 DOMANDE ATTIVE.
-- SQL idempotente: una nuova esecuzione non duplica i codici della nuova banca.
BEGIN;
SELECT pg_advisory_xact_lock(hashtext('k9-academy-dogsitter-600-20261022'));
CREATE TEMP TABLE _dogsitter_import (
 code text PRIMARY KEY, discipline text, category text, difficulty text,
 question_text text, option_a text, option_b text, option_c text, option_d text,
 correct_option smallint, explanation text, active boolean
) ON COMMIT DROP;
DO $$
BEGIN
 IF (SELECT count(*) FROM _dogsitter_import) <> 600 THEN
  RAISE EXCEPTION 'Import incompleto: attese 600 domande';
 END IF;
 IF EXISTS (SELECT 1 FROM _dogsitter_import WHERE discipline <> 'dogsitter' OR correct_option NOT BETWEEN 0 AND 3) THEN
  RAISE EXCEPTION 'Disciplina o risposta corretta non valida';
 END IF;
 IF EXISTS (SELECT 1 FROM _dogsitter_import GROUP BY question_text HAVING count(*)>1) THEN
  RAISE EXCEPTION 'Domande duplicate nel file di import';
 END IF;
 IF EXISTS (SELECT 1 FROM _dogsitter_import t JOIN public.question_bank q ON q.code=t.code WHERE q.discipline <> 'dogsitter') THEN
  RAISE EXCEPTION 'Collisione codice con un altra disciplina: import annullato';
 END IF;
END $$;
-- Disattiva la banca Dogsitter precedente senza eliminare riferimenti storici.
UPDATE public.question_bank SET active=false, updated_at=now()
WHERE discipline='dogsitter' AND active=true;
-- Inserisci/aggiorna le 600 domande, senza toccare altre discipline.
SELECT code,discipline,category,difficulty,question_text,option_a,option_b,option_c,option_d,correct_option,explanation,active,now(),now() FROM _dogsitter_import
ON CONFLICT (code) DO UPDATE SET
 category=EXCLUDED.category,difficulty=EXCLUDED.difficulty,
 question_text=EXCLUDED.question_text,option_a=EXCLUDED.option_a,
 option_b=EXCLUDED.option_b,option_c=EXCLUDED.option_c,
 option_d=EXCLUDED.option_d,correct_option=EXCLUDED.correct_option,
 explanation=EXCLUDED.explanation,active=true,updated_at=now();
DO $$
DECLARE n integer;
BEGIN
 SELECT count(*) INTO n FROM public.question_bank WHERE discipline='dogsitter' AND active=true;
 IF n <> 600 THEN RAISE EXCEPTION 'Verifica fallita: attese 600 attive, trovate %',n; END IF;
END $$;
COMMIT;
-- Verifica post-import:
SELECT discipline,count(*) FILTER (WHERE active) AS domande_attive,
 count(*) AS totale_incluso_storico
FROM public.question_bank GROUP BY discipline ORDER BY discipline;
