INSERT INTO _dogsitter_import (code,discipline,category,difficulty,question_text,option_a,option_b,option_c,option_d,correct_option,explanation,active) VALUES
('DOGS-2026-0001','dogsitter','Banca unica Dogsitter','medio','Quale attività rientra nella cura quotidiana svolta dal dog sitter quando il proprietario è assente?','Gestire passeggiate, pasti, gioco e riposo adeguati','Formulare diagnosi veterinarie','Modificare autonomamente terapie farmacologiche','Prescrivere trattamenti sanitari',0,'Risposta corretta: Gestire passeggiate, pasti, gioco e riposo adeguati. Fonte: Modulo 01, pag. 1. Testo di riferimento: «CORSO DOG SITTER MILANO: Formazione teorica e pratica Chi è il dog sitter? Il dog sitter è una figura che si occupa della cura quotidiana del cane quando il proprietario è assente. Può svolgere passeggiate, gestire pasti, offrire gioco, riposo e attività adeguate all’animale.».',true),
('DOGS-2026-0002','dogsitter','Banca unica Dogsitter','medio','Quando il proprietario è assente, quali compiti quotidiani può assumere il dog sitter?','Modificare autonomamente terapie farmacologiche','Prescrivere trattamenti sanitari','Gestire passeggiate, pasti, gioco e riposo adeguati','Formulare diagnosi veterinarie',2,'Risposta corretta: Gestire passeggiate, pasti, gioco e riposo adeguati. Fonte: Modulo 01, pag. 1. Testo di riferimento: «CORSO DOG SITTER MILANO: Formazione teorica e pratica Chi è il dog sitter? Il dog sitter è una figura che si occupa della cura quotidiana del cane quando il proprietario è assente. Può svolgere passeggiate, gestire pasti, offrire gioco, riposo e attività adeguate all’animale.».',true),
('DOGS-2026-0003','dogsitter','Banca unica Dogsitter','medio','Quale insieme di attività descrive un servizio di dog sitting senza invadere competenze veterinarie?','Modificare autonomamente terapie farmacologiche','Prescrivere trattamenti sanitari','Gestire passeggiate, pasti, gioco e riposo adeguati','Formulare diagnosi veterinarie',2,'Risposta corretta: Gestire passeggiate, pasti, gioco e riposo adeguati. Fonte: Modulo 01, pag. 1. Testo di riferimento: «CORSO DOG SITTER MILANO: Formazione teorica e pratica Chi è il dog sitter? Il dog sitter è una figura che si occupa della cura quotidiana del cane quando il proprietario è assente. Può svolgere passeggiate, gestire pasti, offrire gioco, riposo e attività adeguate all’animale.».',true),
('DOGS-2026-0004','dogsitter','Banca unica Dogsitter','medio','Quale condizione riguarda la somministrazione di medicinali da parte del dog sitter?','Sostituire il veterinario nella diagnosi','Cambiare il dosaggio in base all’umore del cane','Seguire istruzioni precise condivise con proprietario e veterinario','Prescrivere autonomamente il farmaco',2,'Risposta corretta: Seguire istruzioni precise condivise con proprietario e veterinario. Fonte: Modulo 01, pag. 1. Testo di riferimento: «oco, riposo e attività adeguate all’animale. L’eventuale somministrazione di medicinali deve seguire istruzioni precise e condivise con il proprietario e il medico veterinario. Il dog sitter non sostituisce il veterinario. Il servizio può essere saltuario opp».',true),
('DOGS-2026-0005','dogsitter','Banca unica Dogsitter','medio','Se il cane assume un medicinale, a quali indicazioni deve attenersi il dog sitter?','Cambiare il dosaggio in base all’umore del cane','Seguire istruzioni precise condivise con proprietario e veterinario','Sostituire il veterinario nella diagnosi','Prescrivere autonomamente il farmaco',1,'Risposta corretta: Seguire istruzioni precise condivise con proprietario e veterinario. Fonte: Modulo 01, pag. 1. Testo di riferimento: «oco, riposo e attività adeguate all’animale. L’eventuale somministrazione di medicinali deve seguire istruzioni precise e condivise con il proprietario e il medico veterinario. Il dog sitter non sostituisce il veterinario. Il servizio può essere saltuario opp».',true),
('DOGS-2026-0006','dogsitter','Banca unica Dogsitter','medio','Quale limite professionale vale prima di somministrare farmaci al cane affidato?','Sostituire il veterinario nella diagnosi','Cambiare il dosaggio in base all’umore del cane','Seguire istruzioni precise condivise con proprietario e veterinario','Prescrivere autonomamente il farmaco',2,'Risposta corretta: Seguire istruzioni precise condivise con proprietario e veterinario. Fonte: Modulo 01, pag. 1. Testo di riferimento: «oco, riposo e attività adeguate all’animale. L’eventuale somministrazione di medicinali deve seguire istruzioni precise e condivise con il proprietario e il medico veterinario. Il dog sitter non sostituisce il veterinario. Il servizio può essere saltuario opp».',true),
('DOGS-2026-0007','dogsitter','Banca unica Dogsitter','medio','Quale affermazione descrive correttamente il genere Canis?','È un gruppo più ristretto all’interno dei Canidae','Coincide con tutti i mammiferi','Include ogni carnivoro vivente','È un sinonimo di famiglia Felidae',0,'Risposta corretta: È un gruppo più ristretto all’interno dei Canidae. Fonte: Modulo 01, pag. 3. Testo di riferimento: «rende lupi, volpi, sciacalli e altri canidi. Il genere Canis è un gruppo più ristretto all’interno della famiglia. Canis lepophagus è una specie fossile del genere Canis, documentata anche in depositi del Pliocene nordamerican».',true),
('DOGS-2026-0008','dogsitter','Banca unica Dogsitter','medio','In tassonomia, come si colloca il genere Canis rispetto alla famiglia dei canidi?','È un sinonimo di famiglia Felidae','Coincide con tutti i mammiferi','Include ogni carnivoro vivente','È un gruppo più ristretto all’interno dei Canidae',3,'Risposta corretta: È un gruppo più ristretto all’interno dei Canidae. Fonte: Modulo 01, pag. 3. Testo di riferimento: «rende lupi, volpi, sciacalli e altri canidi. Il genere Canis è un gruppo più ristretto all’interno della famiglia. Canis lepophagus è una specie fossile del genere Canis, documentata anche in depositi del Pliocene nordamerican».',true),
('DOGS-2026-0009','dogsitter','Banca unica Dogsitter','medio','Quale descrizione distingue correttamente il genere Canis dalla famiglia Canidae?','Coincide con tutti i mammiferi','È un sinonimo di famiglia Felidae','È un gruppo più ristretto all’interno dei Canidae','Include ogni carnivoro vivente',2,'Risposta corretta: È un gruppo più ristretto all’interno dei Canidae. Fonte: Modulo 01, pag. 3. Testo di riferimento: «rende lupi, volpi, sciacalli e altri canidi. Il genere Canis è un gruppo più ristretto all’interno della famiglia. Canis lepophagus è una specie fossile del genere Canis, documentata anche in depositi del Pliocene nordamerican».',true),
('DOGS-2026-0010','dogsitter','Banca unica Dogsitter','medio','Quale specie fossile viene citata nel materiale didattico?','Bos taurus','Felis catus','Canis lepophagus','Equus caballus',2,'Risposta corretta: Canis lepophagus. Fonte: Modulo 01, pag. 3. Testo di riferimento: «po più ristretto all’interno della famiglia. Canis lepophagus è una specie fossile del genere Canis, documentata anche in depositi del Pliocene nordamericano: non è corretto collocarla in modo certo a 10 milioni di anni fa».',true),
('DOGS-2026-0011','dogsitter','Banca unica Dogsitter','medio','Quale esempio di specie fossile appartenente al genere Canis riporta il corso?','Felis catus','Equus caballus','Canis lepophagus','Bos taurus',2,'Risposta corretta: Canis lepophagus. Fonte: Modulo 01, pag. 3. Testo di riferimento: «po più ristretto all’interno della famiglia. Canis lepophagus è una specie fossile del genere Canis, documentata anche in depositi del Pliocene nordamericano: non è corretto collocarla in modo certo a 10 milioni di anni fa».',true),
('DOGS-2026-0012','dogsitter','Banca unica Dogsitter','medio','Tra le specie indicate, quale è citata a proposito dei fossili del genere Canis?','Bos taurus','Felis catus','Equus caballus','Canis lepophagus',3,'Risposta corretta: Canis lepophagus. Fonte: Modulo 01, pag. 3. Testo di riferimento: «po più ristretto all’interno della famiglia. Canis lepophagus è una specie fossile del genere Canis, documentata anche in depositi del Pliocene nordamericano: non è corretto collocarla in modo certo a 10 milioni di anni fa».',true),
('DOGS-2026-0013','dogsitter','Banca unica Dogsitter','medio','Qual è la differenza fondamentale tra domesticazione e addestramento?','Sono sinonimi che descrivono la stessa attività','La domesticazione coincide con insegnare il seduto','La domesticazione è un processo biologico e culturale di lunga durata','L’addestramento riguarda soltanto i lupi selvatici',2,'Risposta corretta: La domesticazione è un processo biologico e culturale di lunga durata. Fonte: Modulo 01, pag. 4. Testo di riferimento: «o scenario lineare valido per tutte le fasi. L’addomesticamento è un processo biologico e culturale di lunga durata, diverso dall’addestramento di un singolo animale.».',true),
('DOGS-2026-0014','dogsitter','Banca unica Dogsitter','medio','Perché non bisogna confondere la domesticazione con l''educazione di un solo cane?','La domesticazione è un processo biologico e culturale di lunga durata','Sono sinonimi che descrivono la stessa attività','L’addestramento riguarda soltanto i lupi selvatici','La domesticazione coincide con insegnare il seduto',0,'Risposta corretta: La domesticazione è un processo biologico e culturale di lunga durata. Fonte: Modulo 01, pag. 4. Testo di riferimento: «o scenario lineare valido per tutte le fasi. L’addomesticamento è un processo biologico e culturale di lunga durata, diverso dall’addestramento di un singolo animale.».',true),
('DOGS-2026-0015','dogsitter','Banca unica Dogsitter','medio','Nella storia del rapporto uomo-cane, che genere di processo è la domesticazione?','La domesticazione coincide con insegnare il seduto','L’addestramento riguarda soltanto i lupi selvatici','Sono sinonimi che descrivono la stessa attività','La domesticazione è un processo biologico e culturale di lunga durata',3,'Risposta corretta: La domesticazione è un processo biologico e culturale di lunga durata. Fonte: Modulo 01, pag. 4. Testo di riferimento: «o scenario lineare valido per tutte le fasi. L’addomesticamento è un processo biologico e culturale di lunga durata, diverso dall’addestramento di un singolo animale.».',true),
('DOGS-2026-0016','dogsitter','Banca unica Dogsitter','medio','Che cosa descrive uno standard di razza?','Il numero di passeggiate giornaliere richieste','Un obbligo veterinario valido per ogni meticcio','La certezza del carattere di ogni singolo cane','Caratteristiche morfologiche e, se previste, comportamentali di riferimento',3,'Risposta corretta: Caratteristiche morfologiche e, se previste, comportamentali di riferimento. Fonte: Modulo 01, pag. 8. Testo di riferimento: «tto moderno. Che cos’è lo standard di razza? Lo standard è una descrizione di riferimento delle caratteristiche morfologiche e, dove previste, comportamentali tipiche di una razza secondo l’organizzazione che lo adotta. Le associ».',true),
('DOGS-2026-0017','dogsitter','Banca unica Dogsitter','medio','Qual è il contenuto tipico di uno standard adottato da un''organizzazione cinofila?','La certezza del carattere di ogni singolo cane','Il numero di passeggiate giornaliere richieste','Caratteristiche morfologiche e, se previste, comportamentali di riferimento','Un obbligo veterinario valido per ogni meticcio',2,'Risposta corretta: Caratteristiche morfologiche e, se previste, comportamentali di riferimento. Fonte: Modulo 01, pag. 8. Testo di riferimento: «tto moderno. Che cos’è lo standard di razza? Lo standard è una descrizione di riferimento delle caratteristiche morfologiche e, dove previste, comportamentali tipiche di una razza secondo l’organizzazione che lo adotta. Le associ».',true),
('DOGS-2026-0018','dogsitter','Banca unica Dogsitter','medio','Quando un allevatore consulta uno standard di razza, quali caratteristiche vi trova descritte?','La certezza del carattere di ogni singolo cane','Un obbligo veterinario valido per ogni meticcio','Caratteristiche morfologiche e, se previste, comportamentali di riferimento','Il numero di passeggiate giornaliere richieste',2,'Risposta corretta: Caratteristiche morfologiche e, se previste, comportamentali di riferimento. Fonte: Modulo 01, pag. 8. Testo di riferimento: «tto moderno. Che cos’è lo standard di razza? Lo standard è una descrizione di riferimento delle caratteristiche morfologiche e, dove previste, comportamentali tipiche di una razza secondo l’organizzazione che lo adotta. Le associ».',true),
('DOGS-2026-0019','dogsitter','Banca unica Dogsitter','medio','Dove può essere svolto il servizio di dog sitting secondo il corso?','Soltanto nell''abitazione del dog sitter, senza verifiche','Unicamente nei parchi pubblici','Al domicilio del proprietario o in strutture idonee alla custodia','Esclusivamente in un ambulatorio veterinario',2,'Risposta corretta: Al domicilio del proprietario o in strutture idonee alla custodia. Fonte: Modulo 01, pag. 2. Testo di riferimento: «Dove lavora il dog sitter? Il servizio può svolgersi al domicilio del proprietario, anche con permanenza concordata, oppure in strutture idonee alla custodia degli animali.».',true),
('DOGS-2026-0020','dogsitter','Banca unica Dogsitter','medio','In quali luoghi può essere prestato il servizio di accudimento del cane?','Unicamente nei parchi pubblici','Soltanto nell''abitazione del dog sitter, senza verifiche','Esclusivamente in un ambulatorio veterinario','Al domicilio del proprietario o in strutture idonee alla custodia',3,'Risposta corretta: Al domicilio del proprietario o in strutture idonee alla custodia. Fonte: Modulo 01, pag. 2. Testo di riferimento: «Dove lavora il dog sitter? Il servizio può svolgersi al domicilio del proprietario, anche con permanenza concordata, oppure in strutture idonee alla custodia degli animali.».',true),
('DOGS-2026-0021','dogsitter','Banca unica Dogsitter','medio','Il dog sitter opera solo in una struttura esterna? Quali sedi vengono ammesse dal PDF?','Unicamente nei parchi pubblici','Al domicilio del proprietario o in strutture idonee alla custodia','Esclusivamente in un ambulatorio veterinario','Soltanto nell''abitazione del dog sitter, senza verifiche',1,'Risposta corretta: Al domicilio del proprietario o in strutture idonee alla custodia. Fonte: Modulo 01, pag. 2. Testo di riferimento: «Dove lavora il dog sitter? Il servizio può svolgersi al domicilio del proprietario, anche con permanenza concordata, oppure in strutture idonee alla custodia degli animali.».',true),
('DOGS-2026-0022','dogsitter','Banca unica Dogsitter','medio','Come va interpretata la data di circa 15.000 anni nella storia del cane domestico?','Come data dimostrata della nascita di ogni cane domestico.','Come data esatta della prima razza registrata.','Come data della prima vaccinazione canina.','Come riferimento prudenziale per alcune testimonianze archeologiche, non come data unica certa',3,'Risposta corretta: Come riferimento prudenziale per alcune testimonianze archeologiche, non come data unica certa. Fonte: Modulo 01, pag. 5. Testo di riferimento: «Il valore di circa 15.000 anni può essere usato come riferimento prudenziale per alcune testimonianze archeologiche, ma non come data di nascita certa e unica della specie domestica.».',true),
('DOGS-2026-0023','dogsitter','Banca unica Dogsitter','medio','Quale cautela deve accompagnare l''indicazione archeologica dei 15.000 anni?','Come data dimostrata della nascita di ogni cane domestico.','Come data della prima vaccinazione canina.','Come riferimento prudenziale per alcune testimonianze archeologiche, non come data unica certa','Come data esatta della prima razza registrata.',2,'Risposta corretta: Come riferimento prudenziale per alcune testimonianze archeologiche, non come data unica certa. Fonte: Modulo 01, pag. 5. Testo di riferimento: «Il valore di circa 15.000 anni può essere usato come riferimento prudenziale per alcune testimonianze archeologiche, ma non come data di nascita certa e unica della specie domestica.».',true),
('DOGS-2026-0024','dogsitter','Banca unica Dogsitter','medio','Se un corsista afferma che il cane domestico nacque esattamente 15.000 anni fa, quale rettifica è necessaria?','Come data della prima vaccinazione canina.','Come data dimostrata della nascita di ogni cane domestico.','Come data esatta della prima razza registrata.','Come riferimento prudenziale per alcune testimonianze archeologiche, non come data unica certa',3,'Risposta corretta: Come riferimento prudenziale per alcune testimonianze archeologiche, non come data unica certa. Fonte: Modulo 01, pag. 5. Testo di riferimento: «Il valore di circa 15.000 anni può essere usato come riferimento prudenziale per alcune testimonianze archeologiche, ma non come data di nascita certa e unica della specie domestica.».',true),
('DOGS-2026-0025','dogsitter','Banca unica Dogsitter','medio','Lo standard di razza permette di prevedere con certezza il comportamento del singolo cane?','No, contano anche salute, esperienze, genetica individuale e ambiente','Sì, se il cane ha un pedigree.','Sì, indipendentemente dalla sua storia.','Sì, in ogni situazione.',0,'Risposta corretta: No, contano anche salute, esperienze, genetica individuale e ambiente. Fonte: Modulo 01, pag. 8. Testo di riferimento: «Esso non consente tuttavia di prevedere in modo assoluto il comportamento del singolo cane: salute, esperienze, genetica individuale e ambiente restano determinanti. Fonti e note di verifica Le informazioni rettificate sono state confrontate con queste fonti.».',true),
('DOGS-2026-0026','dogsitter','Banca unica Dogsitter','medio','La descrizione standardizzata della razza è sufficiente a predire le reazioni di un individuo?','Sì, indipendentemente dalla sua storia.','Sì, se il cane ha un pedigree.','Sì, in ogni situazione.','No, contano anche salute, esperienze, genetica individuale e ambiente',3,'Risposta corretta: No, contano anche salute, esperienze, genetica individuale e ambiente. Fonte: Modulo 01, pag. 8. Testo di riferimento: «Esso non consente tuttavia di prevedere in modo assoluto il comportamento del singolo cane: salute, esperienze, genetica individuale e ambiente restano determinanti. Fonti e note di verifica Le informazioni rettificate sono state confrontate con queste fonti.».',true),
('DOGS-2026-0027','dogsitter','Banca unica Dogsitter','medio','Quali ulteriori fattori richiedono prudenza nell''uso dello standard come previsione comportamentale?','Sì, in ogni situazione.','Sì, se il cane ha un pedigree.','Sì, indipendentemente dalla sua storia.','No, contano anche salute, esperienze, genetica individuale e ambiente',3,'Risposta corretta: No, contano anche salute, esperienze, genetica individuale e ambiente. Fonte: Modulo 01, pag. 8. Testo di riferimento: «Esso non consente tuttavia di prevedere in modo assoluto il comportamento del singolo cane: salute, esperienze, genetica individuale e ambiente restano determinanti. Fonti e note di verifica Le informazioni rettificate sono state confrontate con queste fonti.».',true),
('DOGS-2026-0028','dogsitter','Banca unica Dogsitter','medio','Come descrive il modulo l''evoluzione dei mammiferi e dei carnivori?','Attraverso un cambiamento improvviso in pochi secoli','Attraverso processi graduali durati milioni di anni','Esclusivamente tramite selezione artificiale moderna','Con un''unica mutazione in epoca storica',1,'Risposta corretta: Attraverso processi graduali durati milioni di anni. Fonte: Modulo 01, pag. 3. Testo di riferimento: «Nozioni sull’evoluzione dei canidi L’evoluzione dei mammiferi e dei carnivori è avvenuta attraverso processi graduali, durati milioni di anni.».',true),
('DOGS-2026-0029','dogsitter','Banca unica Dogsitter','medio','Quale scala temporale caratterizza i processi evolutivi descritti?','Attraverso un cambiamento improvviso in pochi secoli','Esclusivamente tramite selezione artificiale moderna','Con un''unica mutazione in epoca storica','Attraverso processi graduali durati milioni di anni',3,'Risposta corretta: Attraverso processi graduali durati milioni di anni. Fonte: Modulo 01, pag. 3. Testo di riferimento: «Nozioni sull’evoluzione dei canidi L’evoluzione dei mammiferi e dei carnivori è avvenuta attraverso processi graduali, durati milioni di anni.».',true),
('DOGS-2026-0030','dogsitter','Banca unica Dogsitter','medio','Un corsista sostiene che i carnivori siano comparsi all''improvviso: quale alternativa rispetta il testo?','Attraverso processi graduali durati milioni di anni','Attraverso un cambiamento improvviso in pochi secoli','Con un''unica mutazione in epoca storica','Esclusivamente tramite selezione artificiale moderna',0,'Risposta corretta: Attraverso processi graduali durati milioni di anni. Fonte: Modulo 01, pag. 3. Testo di riferimento: «Nozioni sull’evoluzione dei canidi L’evoluzione dei mammiferi e dei carnivori è avvenuta attraverso processi graduali, durati milioni di anni.».',true),
('DOGS-2026-0031','dogsitter','Banca unica Dogsitter','medio','Chi erano i miacidi menzionati nel modulo evolutivo?','Una popolazione attuale di lupi','Le prime razze canine moderne','Piccoli mammiferi carnivori estinti','Un gruppo di rettili domestici',2,'Risposta corretta: Piccoli mammiferi carnivori estinti. Fonte: Modulo 01, pag. 3. Testo di riferimento: «Tra i carnivori primitivi sono spesso ricordati i miacidi, piccoli mammiferi estinti, ma la ricostruzione delle linee evolutive è complessa.».',true),
('DOGS-2026-0032','dogsitter','Banca unica Dogsitter','medio','Quale descrizione zoologica corrisponde ai miacidi del materiale?','Le prime razze canine moderne','Piccoli mammiferi carnivori estinti','Un gruppo di rettili domestici','Una popolazione attuale di lupi',1,'Risposta corretta: Piccoli mammiferi carnivori estinti. Fonte: Modulo 01, pag. 3. Testo di riferimento: «Tra i carnivori primitivi sono spesso ricordati i miacidi, piccoli mammiferi estinti, ma la ricostruzione delle linee evolutive è complessa.».',true),
('DOGS-2026-0033','dogsitter','Banca unica Dogsitter','medio','In una ricostruzione sui carnivori primitivi, come vanno classificati i miacidi?','Piccoli mammiferi carnivori estinti','Le prime razze canine moderne','Un gruppo di rettili domestici','Una popolazione attuale di lupi',0,'Risposta corretta: Piccoli mammiferi carnivori estinti. Fonte: Modulo 01, pag. 3. Testo di riferimento: «Tra i carnivori primitivi sono spesso ricordati i miacidi, piccoli mammiferi estinti, ma la ricostruzione delle linee evolutive è complessa.».',true),
('DOGS-2026-0034','dogsitter','Banca unica Dogsitter','medio','A quali popolazioni collegano la domesticazione del cane le evidenze genetiche riportate?','Antiche popolazioni di lupi','Tutte le specie attuali di sciacallo','Le volpi rosse domesticate in tempi recenti','Il coyote moderno come unico progenitore',0,'Risposta corretta: Antiche popolazioni di lupi. Fonte: Modulo 01, pag. 3. Testo di riferimento: «Le evidenze genetiche collegano la domesticazione del cane a antiche popolazioni di lupi.».',true),
('DOGS-2026-0035','dogsitter','Banca unica Dogsitter','medio','Secondo la ricostruzione citata, da quale gruppo derivano le origini domestiche del cane?','Antiche popolazioni di lupi','Tutte le specie attuali di sciacallo','Le volpi rosse domesticate in tempi recenti','Il coyote moderno come unico progenitore',0,'Risposta corretta: Antiche popolazioni di lupi. Fonte: Modulo 01, pag. 3. Testo di riferimento: «Le evidenze genetiche collegano la domesticazione del cane a antiche popolazioni di lupi.».',true),
('DOGS-2026-0036','dogsitter','Banca unica Dogsitter','medio','Durante una lezione sulle origini canine, quale popolazione è indicata come collegata alla domesticazione?','Antiche popolazioni di lupi','Tutte le specie attuali di sciacallo','Le volpi rosse domesticate in tempi recenti','Il coyote moderno come unico progenitore',0,'Risposta corretta: Antiche popolazioni di lupi. Fonte: Modulo 01, pag. 3. Testo di riferimento: «Le evidenze genetiche collegano la domesticazione del cane a antiche popolazioni di lupi.».',true),
('DOGS-2026-0037','dogsitter','Banca unica Dogsitter','medio','Che cosa dice il modulo sull''identificazione precisa delle origini del cane?','Si ricavano esclusivamente dalla forma delle orecchie','Sono stati stabiliti con certezza nel secolo scorso','Il luogo e la popolazione progenitrice esatti restano oggetto di ricerca','Sono definitivamente noti e identici in tutti gli studi',2,'Risposta corretta: Il luogo e la popolazione progenitrice esatti restano oggetto di ricerca. Fonte: Modulo 01, pag. 3. Testo di riferimento: «L’esatta popolazione progenitrice, il luogo e la sequenza degli eventi sono tuttora materia di ricerca.».',true),
('DOGS-2026-0038','dogsitter','Banca unica Dogsitter','medio','Quale grado di certezza ha la ricostruzione di luogo e progenitore della domesticazione?','Il luogo e la popolazione progenitrice esatti restano oggetto di ricerca','Sono definitivamente noti e identici in tutti gli studi','Sono stati stabiliti con certezza nel secolo scorso','Si ricavano esclusivamente dalla forma delle orecchie',0,'Risposta corretta: Il luogo e la popolazione progenitrice esatti restano oggetto di ricerca. Fonte: Modulo 01, pag. 3. Testo di riferimento: «L’esatta popolazione progenitrice, il luogo e la sequenza degli eventi sono tuttora materia di ricerca.».',true),
